import {TALENT_LEVELS,talentChoices,activeTalents,chooseTalent} from './talents.js';
import {trainingGoals,goalDescription} from './training-goals.js';
import {selectPets} from './collection.js';
import {ELEMENT_REACTIONS,reactionFor} from './reactions.js';
import {GAME_VERSION} from './rules.js';
import {readSaveData,saveEnvelope,createDesktopSaveWriter} from './saves.js';
import {equippedRelic,battleEquipment,itemStats,describeItem,itemXpToNext,TRAINING_DROP_CHANCE,resolveTrainingLoot} from './relics.js';
import {equippedMoves,skillLibrary,setSkillLoadout} from './skills.js';
import {bossProfile} from './bosses.js';
import {GROWTH_STAGES,growthStage} from './stages.js';
import {TrainingLoop} from './autotraining.js';
import {species,petSpecies,legends,legendFor,basicMove,learnsets,elementalLearnsets,abilityElement,isRecovery,isBarrier} from './catalog.js';
