import {renderSpellEffect,mountBattleMotion} from './effects.js';
import {abilities,items,statuses,roles,elements,resolveRole,elementMultiplier,legalTargets,starters,wilds,preparePet,createBattle,available,performAction,enemyPlan,finishRound,hasReady,consumeStuns,attackMultiplier} from './combat.js';
import {defaultSave,restoreSave,equipItem} from './storage.js';
const app=document.querySelector('#app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=defaultSave(),selected='moss',view='sanctuary',battle=null,busy=false,animation=null,notice='',actorId=null,targetId=null,moveId='bite',showLog=false,chosenFloor=1,autoTier='gentle';
const bagSelection={};
const nativeApp=window.lumenwildApp||null;
let nativeUpdateState={phase:nativeApp?'idle':'browser',currentVersion:GAME_VERSION,percent:0,message:'Updates download in the background and install when you exit.'};
const desktopBridge=window.LUMENWILD_DESKTOP||null;
let saveBlocked=false,saveStatus=desktopBridge?'Saved to desktop':'Saved in browser';
const desktopWriter=desktopBridge?createDesktopSaveWriter(desktopBridge,{onStatus:message=>{saveStatus=message;const el=document.querySelector('[data-save-state]');if(el)el.textContent=message;}}):null;
try{const raw=desktopBridge?desktopBridge.save:localStorage.getItem('lumenwild-v2')||localStorage.getItem('lumenwild-v1');if(raw)state=restoreSave(readSaveData(raw));}catch(error){saveBlocked=true;notice=error.message+' Automatic saving is paused to protect the existing save. Import a valid backup to continue.';}selected=state.teamIds[0];chosenFloor=Math.min(TOWER_FLOORS,state.tower.highestCleared+1);
if(desktopBridge?.recovered)notice='Your previous-save backup was recovered. Your companions are ready.';
function save(){if(saveBlocked)return false;try{if(desktopWriter){desktopWriter.write(state).catch(error=>{notice=error.message;render();});}else localStorage.setItem('lumenwild-v2',JSON.stringify({...state,saveVersion:1,gameVersion:GAME_VERSION}));return true;}catch{notice='Saving is unavailable. Open Saves and export a backup before closing.';return false;}}
function header(){return `<header><a class="brand" href="#" data-view="sanctuary"><span class="brand-mark">✳</span> lumenwild<span class="alpha">v${GAME_VERSION}</span></a><nav aria-label="Main navigation">${[['sanctuary','Sanctuary'],['adventure','Adventure'],['creator','Pet studio'],['saves','Saves']].map(([id,label])=>`<button data-view="${id}" class="${view===id||(id==='adventure'&&view==='battle')||(id==='sanctuary'&&view==='pet')?'active':''}" ${busy||trainer.running?'disabled':''}>${label}</button>`).join('')}</nav><span class="saved"><i></i><span data-save-state>${esc(saveStatus)}</span>${nativeApp?`<button class="update-indicator" id="update-indicator" data-view="saves" ${nativeUpdateState.phase==='ready'?'':'hidden'}>Update ready ↗</button>`:''}</span></header>`;}
function render(){app.innerHTML=header()+`<main>${accountBanner()}${notice?`<div class="notice" role="status">${esc(notice)}<button id="dismiss" aria-label="Dismiss notification">×</button></div>`:''}${view==='sanctuary'?sanctuary():view==='creator'?creator():view==='adventure'?adventure():view==='pet'?petDetails():view==='saves'?saveScreen():arena()}</main><footer><span>Made of little moments & a little magic.</span><span>LUMENWILD <b>✧</b> An original creature adventure</span></footer>`;bind();if(view==='battle'&&animation)mountBattleMotion(animation,state.quickAnimations);}
function teamBar(){return `<section class="team-builder"><div><p class="eyebrow">STRONGER TOGETHER</p><h2>Your battle team <span>${state.teamIds.length}/3</span></h2><p>Choose up to three pets from your collection.</p></div><div class="team-slots">${Array.from({length:3},(_,i)=>{const p=accountPets(state).find(p=>p.id===state.teamIds[i]);return p?`<button data-select="${esc(p.id)}" class="team-slot" style="--pet:${p.color}">${petArt(p)}<span>${esc(p.name)} · Lv.${progressionOf(p).level}<small>${roles[p.role].icon} ${roles[p.role].name} · ${p.element}</small><small>${equippedRelic(state,p.id)?items[equippedRelic(state,p.id).type].name+' · Lv.'+equippedRelic(state,p.id).level:'No item equipped'}</small></span></button>`:'<div class="team-slot empty">＋<span>Open team slot</span></div>';}).join('')}</div><button class="primary" id="explore">Choose adventure ↗</button></section>`;}
function sanctuary(){const p=accountPet(state,state.pets.find(p=>p.id===selected)||state.pets[0]),prepared=preparePet(p,equippedRelic(state,p.id)),collection=selectPets(accountPets(state),state.collection);return `<div class="page-heading"><div><p class="eyebrow">YOUR OWN LITTLE UNIVERSE</p><h1>A little wild.<br>Stronger <em>together.</em></h1><p class="intro">Build your team. Find surprising synergies.<br>A small companion can make a big difference.</p></div><div class="heading-note"><span>✧</span> Three spirits.<br>One extraordinary bond.</div></div>${teamBar()}${roleGuide()}<section class="sanctuary-grid"><div class="featured" style="--pet:${p.color}"><div class="feature-top"><span class="pill">✦ ${state.teamIds.includes(p.id)?'ON YOUR TEAM':'IN YOUR SANCTUARY'}</span>${elementBadge(p.element)}</div><div class="pet-stage"><span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><span class="star s1">✧</span>${petArt(p)}<span class="star s3">✧</span></div><div class="feature-bottom"><div><span class="small-label">ACCOUNT LEVEL ${progressionOf(p).level} · ${growthStage(p).name.toUpperCase()} · ${esc(species[petSpecies(p)])}</span><h2>${esc(p.name)}</h2><p>${esc(p.lore)}</p></div><button class="primary" data-team="${esc(p.id)}">${state.teamIds.includes(p.id)?'Remove from team':'Add to team'} ${state.teamIds.includes(p.id)?'−':'＋'}</button></div></div><aside class="companion-info"><p class="eyebrow">A SPIRIT ALL THEIR OWN</p><h2>A role worth playing.</h2><p>${esc(roles[p.role].description)}</p><div class="stat-row"><span>Combat role</span><b>${roleBadge(p)}</b></div><div class="stat-row"><span>Strong against</span><b>${elements[p.element].beats} · 1.5×</b></div><div class="stat-row"><span>Vitality with equipment</span><b>${prepared.maxHp} HP</b></div><div class="stat-row"><span>Equipped item</span><b>${esc(items[prepared.item]?.name||'None')}</b></div><button class="text-button profile-link" data-inspect="${esc(p.id)}">Full stats & ability path ↗</button>${passiveCard(p)}<h3>Equipped skills · ${prepared.moves.length}/4</h3>${prepared.moves.map(id=>`<div class="move-preview"><span>${abilities[id].icon}</span><div><b>${abilities[id].name}${abilities[id].itemOnly?' · item ability':''}</b><p>${abilities[id].description}</p></div></div>`).join('')}</aside></section><section class="collection"><div class="section-title"><div><p class="eyebrow">YOUR GROWING FAMILY</p><h2>Companions <span>${state.pets.length}</span></h2></div><button class="text-button" data-view="creator">Create a pet ＋</button></div>${collectionControls(collection.length)}<div class="pet-grid">${collection.map(p=>`<article class="pet-card ${selected===p.id?'selected':''}" style="--pet:${p.color}"><button class="select-pet" data-select="${esc(p.id)}"><span class="card-element">${roles[p.role].icon} ${roles[p.role].name} · ${esc(p.element)} · Lv.${progressionOf(p).level} ${state.teamIds.includes(p.id)?'· TEAM':''}</span>${petArt(p)}<span class="card-name">${esc(p.name)} <span>${selected===p.id?'✓':'↗'}</span></span></button><button class="team-toggle" data-team="${esc(p.id)}" aria-label="${state.teamIds.includes(p.id)?'Remove':'Add'} ${esc(p.name)} ${state.teamIds.includes(p.id)?'from':'to'} team">${state.teamIds.includes(p.id)?'✓ On team · remove':'+ Add to team'}</button><button class="inspect-card" data-inspect="${esc(p.id)}">Stats & abilities ↗</button></article>`).join('')}<button class="create-card" data-view="creator"><span>＋</span><b>A spark of your own</b><small>Bring a new companion to life</small></button></div></section>${inventory(p)}${elementGuide()}`;}
function inventory(p){return `<section class="inventory"><div class="section-title"><div><p class="eyebrow">TREASURES THAT GROW ALONGSIDE YOU</p><h2>The item satchel</h2><p class="intro">Equipping <b>${esc(p.name)}</b> · one copy per pet. Equipped items earn battle XP, even at account level 100.<br>Training drop chance: Gentle 35% · Balanced 50% · Challenging 65%. Each copy keeps its own growth.</p></div>${equippedRelic(state,p.id)?'<button class="text-button" id="unequip">Unequip current item</button>':''}</div><div class="item-grid">${Object.entries(items).map(([type,item])=>{
 const copies=state.relics.filter(r=>r.type===type).sort((a,b)=>b.level-a.level||b.xp-a.xp),current=equippedRelic(state,p.id),relic=copies.find(r=>r.id===bagSelection[type])||copies.find(r=>r.id===current?.id)||copies.find(r=>!Object.values(state.equipment).includes(r.id))||copies[0],owner=relic&&state.pets.find(p=>state.equipment[p.id]===relic.id),equipped=owner?.id===p.id,need=relic?itemXpToNext(relic.level):0;
 return `<article class="item-card ${equipped?'equipped':''} ${!relic?'undiscovered-item':''}"><div class="item-top"><span class="item-icon">${item.icon}</span><small>${item.rarity}</small><b>×${copies.length}</b></div><strong>${item.name}</strong><span class="item-level">${relic?'LEVEL '+relic.level+' / 20':'TRAINING DROP'}</span><p>${relic?esc(describeItem(relic)):item.description}</p>${relic?`<label class="copy-label">Relic copy<select data-copy="${type}" aria-label="${item.name} copy">${copies.map(r=>{const who=state.pets.find(p=>state.equipment[p.id]===r.id);return `<option value="${r.id}" ${r.id===relic.id?'selected':''}>Lv.${r.level} · ${r.xp} XP · ${who?esc(who.name):'Available'} · #${r.id.split('-').at(-1)}</option>`;}).join('')}</select></label><div class="item-xp"><i style="width:${need?relic.xp/need*100:100}%"></i></div><small>${need?relic.xp+' / '+need+' item XP to level '+(relic.level+1):'Maximum item level'}</small><button class="relic-equip" data-equip="${relic.id}" ${owner&&!equipped?'disabled':''}>${equipped?'✓ Equipped · unequip':owner?'Worn by '+esc(owner.name):'Equip to '+esc(p.name)}</button>`:'<small>Find this relic in training. Each new copy starts at level 1.</small>'}</article>`;
 }).join('')}</div></section>`;}
function ensureBattle(){if(!battle)launchEncounter('training',1,state.trainingTier,false);fixSelection();}
function fixSelection(){
 if(!battle||battle.outcome||busy)return;
 const ready=battle.players.filter(p=>p.hp>0&&!p.acted&&!p.statuses.stun);
 if(!ready.some(p=>p.cid===actorId))actorId=ready[0]?.cid;
 const actor=battle.players.find(p=>p.cid===actorId);
 if(actor&&!available(actor,moveId))moveId=basicMove(actor);
 const legal=legalTargets(battle,'player',moveId,actorId);
 if(!legal.some(p=>p.cid===targetId))targetId=(legal.find(p=>p.cid===actorId)||legal[0])?.cid;
}
function fighterPanel(p){
 const passive=passiveOf(p),talents=activeTalents(p);
 const a=abilities[moveId],actor=battle.players.find(p=>p.cid===actorId),legal=legalTargets(battle,'player',moveId,actorId);
 const choosing=['ally','enemy'].includes(a.target),canTarget=!busy&&!trainer.running&&!battle.outcome&&choosing&&legal.includes(p);
 const locked=!busy&&!battle.outcome&&a.target==='enemy'&&p.side==='enemy'&&p.hp>0&&!legal.includes(p);
 const selected=p.cid===targetId&&(canTarget||a.target==='self');
 const fx=animation?.effects.filter(e=>e.cid===p.cid)||[],source=animation?.actor===p.cid,affected=animation?.targets.includes(p.cid);
 const offensive=['enemy','allEnemies'].includes(a.target)&&a.power&&actor;
 const multiplier=!busy&&offensive&&p.side==='enemy'&&p.hp>0?elementMultiplier(abilityElement(actor,a),p.element):null;
 return `<button class="team-fighter ${p.side} ${p.legend?'legend-unit':''} ${p.boss?'legend-boss':''} ${p.minion?'summoned-minion':''} ${p.hp<=0?'fainted':''} ${(busy?animation?.actor===p.cid:actorId===p.cid&&!p.acted)?'acting':''} ${selected?'targeted':''} ${locked?'taunt-locked':''} ${source?'casting casting-'+animation.kind:''} ${affected?'effect-'+animation.kind:''} ${fx.some(e=>e.type==='damage'&&e.value>0)?'impact':''}" style="--pet:${p.color}" data-target="${p.cid}" ${!canTarget?'disabled':''} aria-label="${canTarget?'Target ':''}${esc(p.name)}${locked?' protected by taunt':''}${p.hp<=0?' defeated':''}">
 <div class="fighter-label"><h2>${esc(p.name)} <small class="level-badge">Lv.${p.level}</small></h2><span>${p.side==='player'?(p.acted?'DONE':'READY'):(battle.outcome?'':esc(abilities[enemyPlan(battle,p)?.move]?.name||'Acted'))}</span></div>
 <div class="fighter-identity">${roleBadge(p)}${elementBadge(p.element)}<span class="stage-tag">${growthStage(p).name}</span>${p.legend?'<span class="legend-tag">✦ LEGEND</span>':''}${p.minion?'<span class="minion-tag">SUMMONED</span>':''}</div>
 <div class="hp-track" role="progressbar" aria-label="${esc(p.name)} health" aria-valuemin="0" aria-valuemax="${p.maxHp}" aria-valuenow="${p.hp}"><div style="width:${p.hp/p.maxHp*100}%"></div></div>
 <div class="fighter-stats"><span>${p.hp}/${p.maxHp} HP</span><span>${p.item?items[p.item].icon+' Lv.'+p.itemLevel:p.minion?'MINION':p.boss?'BOSS':'4-SKILL KIT'}</span></div>
 <div class="fighter-art">${petArt(p)}${affected?renderSpellEffect(animation.kind,animation.move):''}${fx.length?`<div class="float-effects" aria-hidden="true">${fx.map((e,i)=>`<span class="float-${e.type} ${e.counter?'counter-popup':''}" style="--i:${i}">${esc(e.text)}</span>`).join('')}</div>`:''}</div>
 ${multiplier!==null?`<span class="matchup match-${multiplier>1?'strong':multiplier<1?'weak':'neutral'}">${locked?'♜ Guarded · ':''}${multiplier}× ${multiplier>1?'strong':multiplier<1?'resisted':'neutral'}</span>`:''}
 <div class="status-list">${p.elementalAura?`<span class="elemental-aura" style="--aura:${elements[p.elementalAura.element].color}" title="Hit with another element to trigger a reaction. ${p.elementalAura.remaining} round(s) remaining.">${elements[p.elementalAura.element].icon} ${p.elementalAura.element} aura · ${p.elementalAura.remaining}</span>`:''}${p.side==='player'&&accountProgress(state).level>p.level?'<span class="pending-growth">↗ Level up next encounter</span>':''}${p.passiveStacks?`<span class="status ember-stacks">♨ ${p.passiveStacks} embers · +${p.passiveStacks*6}% attack</span>`:''}<span class="status passive-badge" title="${esc(passive.description)}">${passive.icon} ${passive.name}</span>${talents.map(t=>`<span class="status talent-badge" title="${esc(t.description)}">✧ ${t.name}</span>`).join('')}${p.shield?`<span class="status status-shield" title="Blocks incoming damage until consumed">◈ ${p.shield}</span>`:''}${Object.entries(p.statuses).map(([id,n])=>`<span class="status status-${id}" title="${statuses[id].description} ${n} round(s) remaining">${statuses[id].icon} ${statuses[id].name} ${n}</span>`).join('')}${p.hp<=0?'<span class="status">Resting</span>':''}</div></button>`;
}
function arena(){ensureBattle();const b=battle,actor=b.players.find(p=>p.cid===actorId),a=abilities[moveId];return `<div class="section-title arena-title"><div><p class="eyebrow">THE WHISPERING WILDS · ${esc(b.context.label).toUpperCase()}</p><h1>One team. <em>Many possibilities.</em></h1></div><button class="text-button" id="leave" ${busy||trainer.running?'disabled':''}>← Leave encounter</button></div>${b.context.mode==='training'?autoTrainingPanel():bossBattlePanel(b)}<section data-enemy-count="${b.enemies.length}" class="arena team-arena ${state.quickAnimations?'quick-motion':''} ${animation?'spell-active':''}"><div class="arena-top"><span>✧ ${b.context.mode==='tower'?esc(b.context.theme).toUpperCase():'TRAINING GROUNDS'} · ${b.players.length} vs ${b.enemies.length}</span><span>ROUND ${b.round} · ${b.outcome?'FINISHED':b.phase==='player'?'YOUR TEAM':'ENEMY TEAM'}</span></div><div class="squad-row enemy-squad">${b.enemies.map(fighterPanel).join('')}</div><div class="battle-divider"><span></span><b>✦</b><span></span></div><div class="squad-row player-squad">${b.players.map(fighterPanel).join('')}</div><div class="intent" role="status" aria-live="polite">${animation?.label?esc(animation.label):animation?.move?`${esc([...b.players,...b.enemies].find(p=>p.cid===animation.actor)?.name||'')} casts <b>${abilities[animation.move].name}</b>`:b.outcome?b.outcome==='won'?'✦ Every little spirit made a difference.':b.outcome==='draw'?'Both teams need a little rest.':'Your companions will recover. A new strategy awaits.':busy?'Round-end effects resolve…':battleInstruction()}</div></section>${b.outcome?resultPanel():`<section class="team-commands"><div class="section-title"><div><p class="eyebrow">CHOOSE WHO ACTS NEXT</p><div class="actor-tabs">${b.players.map(p=>`<button data-actor="${p.cid}" class="${actorId===p.cid?'active':''}" ${busy||trainer.running||p.acted||p.hp<=0||p.statuses.stun?'disabled':''}>${esc(p.name)} <small>${p.hp<=0?'Resting':p.acted?'✓ Done':p.statuses.stun?'Stunned':p.moves.filter(id=>available(p,id)).length+' ready'}</small></button>`).join('')}</div></div><div class="battle-tools"><span class="round-tip">Each pet acts once.<br>4 skills · cooldowns only.</span><button class="text-button" id="speed" ${busy||trainer.running?'disabled':''}>Effects: ${state.quickAnimations?'Quick':'Full'}</button></div></div><div class="team-ability-grid">${(actor?.moves||[]).map(id=>{const a=abilities[id];return `<button class="ability ${moveId===id?'chosen':''}" data-move="${id}" ${busy||trainer.running||!available(actor,id)?'disabled':''}><span class="ability-icon">${a.icon}</span><span><b>${a.name}${a.itemOnly?' · relic':a.legendOnly?' · Legend':''}</b><small>${a.description}</small>${a.element?`<small class="ability-element">${elements[a.element].icon} ${a.element}${a.element==='Astral'?' · Lightning':''}</small>`:''}${a.power?`<small class="scaled-power">Current effect power ${battlePower(actor,a)}</small>`:''}</span><span class="cost">${actor.cooldowns[id]?actor.cooldowns[id]+' turns':a.cooldown?a.cooldown+'-turn CD':'BASIC'}</span></button>`;}).join('')}</div><div class="cast-row"><p>${actor?`<b>${esc(actor.name)}</b> → ${a.name} → <b>${targetSummary(actor,a)}</b>${reactionHint(actor,a)}`:'Enemy team is acting…'}</p><button class="primary" id="cast" ${busy||trainer.running||!actor||!available(actor,moveId)?'disabled':''}>Cast ${a.name} ${a.icon}</button></div></section>`}<details class="battle-log" ${showLog?'open':''}><summary>Battle journal <span>${b.log.length} moments</span></summary><ol>${b.log.slice(-35).map(l=>`<li>${esc(l)}</li>`).join('')}</ol></details><details class="effect-guide"><summary>Buffs, debuffs & round rules</summary><div>${Object.entries(statuses).map(([id,s])=>`<p><b>${s.icon} ${s.name}</b> — ${s.description}</p>`).join('')}<p>Statuses count down at round end, including the round they are applied. Shields last until consumed. Fallen pets cannot act, heal, or receive statuses. Cooldowns tick down at round end. A 3-turn skill used on turn 1 is ready on turn 4. Start-of-turn passives fire once per pet action, including skipped stunned actions. All pets fully recover after battle.</p></div></details>${elementGuide()}`;}
function resultPanel(){
 const b=battle,won=b.outcome==='won',growth=accountProgress(state),before=b.players[0].level,replay=b.context.mode==='tower'&&b.context.floor<=state.tower.highestCleared&&!hasLegendReward(state,b.context);
 return `<section class="result progression-result" role="status"><div><p class="eyebrow">${won?'ENCOUNTER COMPLETE':'A LITTLE REST. A NEW STRATEGY.'}</p><h2>${won?(b.context.mode==='tower'?'Floor '+b.context.floor+' conquered.':'Practice makes extraordinary.'):'Every lesson counts.'}</h2><p>${won?(b.claimed?'Rewards collected. Your next encounter is ready.':hasLegendReward(state,b.context)?legendAtFloor(b.context.floor).name+' will join at your account level. Claim your Legend and double relic loot.':replay?'Cleared-floor replay: account XP earned, first-clear loot already collected.':b.context.mode==='training'?'Claim your featured companion if new. Training loot has already been rolled.':'Claim first-clear relic loot and advance the tower.'):'Your earned account XP is kept. Every companion recovers fully between encounters.'}</p>${trainingLootSummary(b)}<p>All pets share your account level. New stats and skills apply next encounter.</p></div><div class="xp-results"><div class="account-xp-result"><span>SHARED ACCOUNT EXPERIENCE</span><strong>+${b.accountXpEarned||0} XP</strong><small>Account level ${before}${growth.level>before?' → '+growth.level+' ✦':''} · all ${state.pets.length} companions</small>${xpBar()}</div>${b.players.filter(member=>member.relicId).map(member=>`<button data-inspect="${esc(member.id)}"><span>${esc(member.name)}’s relic</span><strong>+${b.itemXpEarned[member.relicId]||0} item XP</strong><small>${items[member.item].name} · Lv.${state.relics.find(r=>r.id===member.relicId)?.level||member.itemLevel}</small></button>`).join('')}</div><button class="primary" id="claim" ${trainer.running?'disabled':''}>${won?(b.claimed?'Continue ↗':'Claim & continue ↗'):'Recover & return ↗'}</button></section>`;
}
function petArt(p,cls=''){return renderPet(p,cls);}
function creator(){return `<div class="section-title"><div><p class="eyebrow">THE PET STUDIO</p><h1>A purpose. <em>A personality.</em></h1><p class="intro">Choose their role and element. Give them a signature, then a surprise.</p></div></div><div class="creator-grid"><div class="creator-preview featured"><span class="pill">✧ A WORK OF WONDER</span><div id="live-preview"></div><p>Your animal determines their innate passive.</p></div><form id="pet-form">
 <label>Companion name<input name="name" placeholder="e.g. Moonberry" maxlength="24" required></label>
 <div class="form-row"><label>Animal<select name="species">${Object.entries(species).filter(([id])=>!legends.some(p=>p.species===id)||state.pets.some(p=>legendFor(p)?.species===id)).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></label><label>Spirit color<input type="color" name="color" value="#b8a4ed"></label></div>
 <div class="form-row"><label>Combat role<select name="role">${Object.entries(roles).map(([id,r])=>`<option value="${id}" ${id==='fighter'?'selected':''}>${r.icon} ${r.name}</option>`).join('')}</select></label><label>Starting health<input name="hp" type="number" value="95" readonly aria-label="Starting health from role"></label></div>
 <p id="role-description" class="studio-hint"></p>
 <label>Element<select name="element">${Object.keys(elements).map(id=>`<option>${id}</option>`).join('')}</select></label><p id="element-hint" class="studio-hint"></p>
 <div class="section-title"><h3>Choose two special abilities</h3><small>Include at least one role signature. Wild bite is included.</small></div>
 <div class="move-options" id="move-options">${moveOptions('fighter')}</div><p id="form-error" role="alert"></p><button class="primary" type="submit">Bring to life <span>✧</span></button><p class="form-note">Starts at your account level (${accountProgress(state).level}). Their stats, growth stage, and skill unlocks scale with account level.</p></form></div>${elementGuide()}`;}
function updatePreview(){
 const form=document.querySelector('#pet-form'),f=new FormData(form),role=f.get('role'),element=f.get('element');
 document.querySelector('#live-preview').innerHTML=petArt({name:f.get('name')||'Your companion',species:f.get('species'),shape:'sprout',color:f.get('color'),role,element,level:accountProgress(state).level})+`<h2>${esc(f.get('name')||'Your companion')}</h2><div class="preview-tags">${roleBadge({role})}${elementBadge(element)}</div>`;
 document.querySelector('#role-description').textContent=roles[role].description+' Innate passive: '+passiveOf({id:'preview',role,species:f.get('species'),moves:['bite',...roles[role].defaults]}).name+'.';
 document.querySelector('#element-hint').textContent=`Strong against ${elements[element].beats} (1.5×). Resisted by ${Object.keys(elements).find(id=>elements[id].beats===element)} (0.75×). This element grants its own moves; untyped attacks inherit it.`;
}
function resetBattle(){battle=null;actorId=null;targetId=null;moveId='bite';animation=null;}
function toggleTeam(id){if(state.teamIds.includes(id)){if(state.teamIds.length===1){notice='Keep at least one companion on your team.';render();return;}state.teamIds=state.teamIds.filter(v=>v!==id);}else{if(state.teamIds.length===3){notice='Your team has three pets. Remove one before adding another.';render();return;}state.teamIds.push(id);}resetBattle();notice='';save();render();}
function claimRewards(){if(busy||trainer.running)return;const reward=claimEncounter(state,battle);if(reward){notice=[reward.firstLegendClear?'Legend trial conquered!':reward.firstClear?(state.tower.highestCleared===TOWER_FLOORS?'All 20 floors conquered!':'New tower floor cleared!'):'Adventure complete.',...reward.items.map(i=>`${i.count}× ${items[i.id].name}`),reward.legend?`Legend ${reward.legend} joined at account level ${accountProgress(state).level}.`:reward.pet?`${reward.pet} joined at account level ${accountProgress(state).level}.`:''].filter(Boolean).join(' ');save();}resetBattle();chosenFloor=Math.min(TOWER_FLOORS,state.tower.highestCleared+1);view='adventure';render();}
function bind(){bindTalentControls();bindCollectionControls();bindSaveControls();bindNativeUpdateControls();bindProgression();bindBuildControls();document.querySelector('#dismiss')?.addEventListener('click',()=>{notice='';render();});document.querySelectorAll('[data-view]').forEach(el=>el.onclick=e=>{e.preventDefault();if(busy||trainer.running)return;view=el.dataset.view;render();});document.querySelectorAll('[data-select]').forEach(el=>el.onclick=()=>{selected=el.dataset.select;notice='';render();});document.querySelectorAll('[data-team]').forEach(el=>el.onclick=()=>toggleTeam(el.dataset.team));document.querySelectorAll('[data-equip]').forEach(el=>el.onclick=()=>{if(equipItem(state,selected,el.dataset.equip)){resetBattle();save();notice='';render();}});document.querySelector('#unequip')?.addEventListener('click',()=>{equipItem(state,selected,state.equipment[selected]);resetBattle();save();render();});document.querySelector('#explore')?.addEventListener('click',()=>{view='adventure';notice='';render();});document.querySelector('#leave')?.addEventListener('click',()=>{if(busy||trainer.running)return;resetBattle();view='sanctuary';render();});document.querySelectorAll('[data-actor]').forEach(el=>el.onclick=()=>{if(busy||trainer.running)return;actorId=el.dataset.actor;moveId=basicMove(battle.players.find(p=>p.cid===actorId));targetId=battle.enemies.find(p=>p.hp>0)?.cid;render();});document.querySelectorAll('[data-target]').forEach(el=>el.onclick=()=>{if(!busy&&!trainer.running){targetId=el.dataset.target;render();}});document.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>{if(busy||trainer.running)return;moveId=el.dataset.move;targetId=abilities[moveId].target==='ally'?actorId:battle.enemies.find(p=>p.hp>0)?.cid;render();});document.querySelector('#cast')?.addEventListener('click',()=>act());document.querySelector('#claim')?.addEventListener('click',claimRewards);document.querySelector('.battle-log')?.addEventListener('toggle',e=>{showLog=e.currentTarget.open;});const form=document.querySelector('#pet-form');if(form){updatePreview();form.oninput=e=>{if(e.target.name==='role'){const role=form.elements.role.value;document.querySelector('#move-options').innerHTML=moveOptions(role);form.elements.hp.value=roles[role].hp;}updatePreview();};form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),moves=f.getAll('moves');if(moves.length!==2){document.querySelector('#form-error').textContent='Choose exactly two special abilities.';return;}const role=f.get('role');if(!moves.some(id=>roles[role].core.includes(id))||!moves.every(id=>roles[role].options.includes(id))){document.querySelector('#form-error').textContent='Include a role signature so your pet can fulfill its purpose.';return;}const name=f.get('name').trim();if(!name){document.querySelector('#form-error').textContent='Give your companion a name.';return;}const p={id:crypto.randomUUID(),name,role,color:f.get('color'),species:f.get('species'),shape:'sprout',element:f.get('element'),hp:roles[role].hp,moves:['bite',...moves],lore:'Dreamed up by you. Ready to discover the world.'};p.equippedSkills=equippedMoves(accountPet(state,p));state.pets.push(p);selected=p.id;save();notice='Your new companion is ready. Add them to your team below.';view='sanctuary';render();};}}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function showEvent(event){
 for(const before of event.beforeEvents||[])await showEvent(before);
 const changes=bankBattleXp(state,battle,event);trainer.recordXp(changes.reduce((sum,r)=>sum+r.amount,0));
 const newLoot=battle.outcome&&battle.context.mode==='training'&&!battle.trainingLoot;if(newLoot)resolveTrainingLoot(state,battle);if(changes.length||newLoot)save();
 animation=event;render();await delay(matchMedia('(prefers-reduced-motion: reduce)').matches?140:state.quickAnimations?300:1050);animation=null;
 for(const after of event.afterEvents||[])await showEvent(after);
}
async function act(plan=null){
 if(busy||!battle||(!plan&&trainer.running))return;
 if(plan){actorId=plan.actor;moveId=plan.move;targetId=plan.target;}
 const event=performAction(battle,'player',actorId,moveId,targetId);if(!event)return;busy=true;
 try{await showEvent(event);
  while(!battle.outcome&&battle.phase==='enemy'){
   while(!battle.outcome&&hasReady(battle.enemies)){
    for(const enemy of battle.enemies){if(battle.outcome)break;const next=enemyPlan(battle,enemy);if(next){const result=performAction(battle,'enemy',next.actor,next.move,next.target);if(result)await showEvent(result);}}
   }
   if(battle.outcome)break;
   const skipped=consumeStuns(battle,'enemy');if(skipped.effects.length||skipped.beforeEvents.length)await showEvent(skipped);
   const end=finishRound(battle);if(end&&(end.effects.length||end.beforeEvents.length))await showEvent(end);actorId=null;
  }
 }finally{busy=false;animation=null;fixSelection();render();}
}

const trainer=new TrainingLoop({getBattle:()=>battle,getGoals:()=>state.trainingGoals,getAccountLevel:()=>accountProgress(state).level,act:plan=>act(plan),claim:()=>{const reward=claimEncounter(state,battle);if(reward)save();return reward;},restart:()=>launchEncounter('training',1,autoTier),onUpdate:()=>render()});
render();
if(desktopBridge&&!desktopBridge.save&&!saveBlocked)save();

function roleBadge(p){const role=roles[resolveRole(p)];return `<span class="role-tag role-${resolveRole(p)}" title="${esc(role.description)}">${role.icon} ${role.name}</span>`;}

function elementBadge(element){return `<span class="type-tag" style="--type-color:${elements[element].color}">${elements[element].icon} ${element}</span>`;}

function elementGuide(){return `<details class="type-guide"><summary>Element matchups <span>Strength 1.5× · resistance 0.75×</span></summary><div class="type-cycle">${Object.entries(elements).map(([id,e])=>`${elementBadge(id)}<span class="cycle-arrow">→</span>`).join('')}<small>Each element beats the next. Astral beats Ember.</small></div><p>Elemental abilities use their listed element. Untyped role and relic attacks use the pet’s element. Astral is the lightning element. Healing, shields, burn ticks, and thorns ignore type matchups. Same-element and opposite-element attacks are neutral.</p><div class="table-wrap"><table><caption>Rows attack · columns defend</caption><thead><tr><th>Attack ↓ / Defend →</th>${Object.keys(elements).map(id=>`<th scope="col">${id}</th>`).join('')}</tr></thead><tbody>${Object.keys(elements).map(from=>`<tr><th scope="row">${from}</th>${Object.keys(elements).map(to=>{const n=elementMultiplier(from,to);return `<td class="match-${n>1?'strong':n<1?'weak':'neutral'}">${n}×</td>`;}).join('')}</tr>`).join('')}</tbody></table></div></details>${reactionGuide()}`;}

function roleGuide(){return `<section class="role-guide">${Object.entries(roles).map(([id,r])=>`<div>${roleBadge({role:id})}<p>${r.description}</p></div>`).join('')}</section>`;}

function battleInstruction(){
 const a=abilities[moveId],taunter=battle.enemies.find(p=>p.hp>0&&p.statuses.taunt);
 if(a.target==='self')return `${a.name} targets the acting pet. No other target is needed.`;
 if(a.target==='enemy'&&taunter)return `♜ ${esc(taunter.name)} is taunting: single-target attacks must target this guardian. Area attacks bypass taunts.`;
 if(a.target==='allEnemies')return 'Area attack: hit every living enemy, even while a guardian is taunting.';
 if(a.target==='allAllies')return 'Team ability: affect every living ally.';
 return `Choose an acting pet, an ability, and ${a.target==='ally'?'a friendly target':'an enemy target'}.`;
}

function targetSummary(actor,a){
 if(a.target==='self')return 'self · '+esc(actor.name);
 if(a.target==='allEnemies')return 'all enemies · individual element matchups';
 if(a.target==='allAllies')return 'all allies';
 const target=[...battle.players,...battle.enemies].find(p=>p.cid===targetId);
 if(!target)return 'choose a target';
 const n=elementMultiplier(abilityElement(actor,a),target.element);
 return esc(target.name)+(a.target==='enemy'&&a.power?` · ${n}× ${n>1?'strong':n<1?'resisted':'neutral'}`:'');
}

function moveOptions(role){const r=roles[role];return r.options.map(id=>{const a=abilities[id];return `<label class="move-option"><input type="checkbox" name="moves" value="${id}" ${r.defaults.includes(id)?'checked':''}><span class="ability-icon">${a.icon}</span><span><b>${a.name}${r.core.includes(id)?' <small class="signature">ROLE SIGNATURE</small>':''}</b><small>${a.description} Cooldown: ${a.cooldown||0} turns.</small></span></label>`;}).join('');}

function xpBar(){const {level,xp}=accountProgress(state),need=xpToNext(level);return `<div class="xp-meter" role="progressbar" aria-label="Account experience" aria-valuemin="0" aria-valuemax="${need||1}" aria-valuenow="${need?xp:1}"><i style="width:${need?xp/need*100:100}%"></i></div><span class="xp-caption">${need?xp+' / '+need+' account XP to level '+(level+1):'Maximum level · '+MAX_LEVEL}</span>`;}
function launchEncounter(mode,floor=1,tier=state.trainingTier,draw=true){try{const context=makeEncounter(state,mode,floor,tier);resetBattle();battle=createBattle(state.teamIds.map(id=>accountPet(state,state.pets.find(p=>p.id===id))),context.enemies,battleEquipment(state));battle.context=context;battle.xpMultiplier=context.xpMultiplier;actorId=battle.players[0].cid;targetId=battle.enemies[0].cid;moveId=basicMove(battle.players[0]);view='battle';notice='';if(draw){render();window.scrollTo({top:0,behavior:'instant'});}}catch(error){notice=error.message;view='adventure';if(draw)render();}}
function adventure(){
 const training=makeEncounter(state,'training',1,state.trainingTier),floor=Math.min(TOWER_FLOORS,chosenFloor),tower=makeEncounter(state,'tower',floor);
 return `<div class="page-heading"><div><p class="eyebrow">EVERY ADVENTURE LEAVES A MARK</p><h1>Grow a little.<br>Go <em>a little further.</em></h1><p class="intro">Account level ${accountProgress(state).level} · all companions · ${state.trainingWins} training victories<br>XP is banked on every defeat. New stats and abilities apply next encounter.</p></div><div class="adventure-emblem" aria-hidden="true">✧<span>THE WILDS<br>ARE WAITING</span></div></div>
 ${battle?`<div class="resume-banner"><p>${battle.outcome?'Your encounter results are waiting.':esc(battle.context.label)+' · Round '+battle.round+' in progress.'} Starting another encounter leaves this one; earned XP is kept.</p><button class="text-button" id="resume">${battle.outcome?'Review results':'Resume encounter'} →</button></div>`:''}
 <div class="mode-grid"><section class="mode-card training-card"><div class="mode-heading"><span class="mode-icon">❋</span><span class="pill">REPEATABLE · ACCOUNT GROWTH</span></div><h2>The training glade</h2><p>Train, farm XP, and recruit ordinary companions. Legends join the training roster after their tower trial. A new featured pet is guaranteed on victory.</p><label class="tier-label">Training intensity<select id="training-tier">${Object.entries(trainingTiers).map(([id,t])=>`<option value="${id}" ${state.trainingTier===id?'selected':''}>${t.name} · ${t.count} opponents</option>`).join('')}</select></label><label class="tier-label recruitment-focus">Recruitment focus<select id="training-target">${trainingFocusOptions()}</select></label><div class="recruit-preview-label">Featured: <b>${esc(trainingTargetPet(state).name)}</b> · ${state.pets.some(p=>p.id===training.featuredId)?'already collected':'new companion on victory'}</div><div class="encounter-preview">${training.enemies.map(p=>`<div>${petArt(p)}<strong>${esc(p.name)}</strong><small>Lv.${p.level} · ${p.element}</small></div>`).join('')}</div><div class="mode-meta"><span>${training.enemies.length} opponents · enemy Lv.${training.level}</span><span>+${training.enemies.reduce((sum,p)=>sum+defeatXp(p,training.xpMultiplier),0)} account XP for all kills</span></div>${trainingGoalEditor()}<div class="training-starts"><button class="primary" id="train">Train manually ↗</button><button class="primary auto-start" id="start-auto">Start auto-training ⟳</button></div><p class="auto-help">Auto fights, claims rewards, and repeats. Keep the page open; press Stop to return to manual control.</p></section>
 <section class="mode-card tower-card"><div class="mode-heading"><span class="mode-icon">♜</span><span class="pill">20 FLOORS · 4 LEGEND TRIALS</span></div><h2>The astral spire</h2><p>Account level cap: 100. Each floor adds 5 enemy levels, from level 5 to 100. Every fifth floor is a two-phase Legend boss: empowered stats, a charged special, and up to two minion waves.</p><div class="tower-progress"><span>${state.tower.highestCleared} / ${TOWER_FLOORS} floors cleared</span><div><i style="width:${state.tower.highestCleared/TOWER_FLOORS*100}%"></i></div></div><div class="floor-grid">${Array.from({length:TOWER_FLOORS},(_,i)=>{const n=i+1,locked=n>state.tower.highestCleared+1;return `<button data-floor="${n}" class="${chosenFloor===n?'selected':''} ${n<=state.tower.highestCleared?'cleared':''} ${n%5===0?'boss-floor':''} ${n<=state.tower.highestCleared&&legendAtFloor(n)&&!state.tower.legendClears.includes(n)?'legend-unclaimed':''}" ${locked?'disabled':''} aria-label="Floor ${n}${n%5===0?' Legend '+legendAtFloor(n).name:''}${locked?' locked':n<=state.tower.highestCleared?' cleared':''}">${n%5===0?'♜ ':''}${n}${n<=state.tower.highestCleared?' ✓':''}</button>`;}).join('')}</div><div class="floor-detail"><div><strong>Floor ${floor}${tower.boss?' · Legend '+legendAtFloor(floor).name:''}</strong><small>${tower.theme} · enemy Lv.${tower.level}</small></div><span>${hasLegendReward(state,tower)?'Legend + double relic loot':floor<=state.tower.highestCleared?'Replay · XP only':'First clear · relic loot'}</span></div>${tower.legendId?legendTrialPreview(legendAtFloor(floor),tower.level):''}<div class="tower-enemies">${tower.enemies.map(p=>`<span>${p.boss?'✦ ':''}${esc(p.name)}<small>${roles[p.role].name} · ${p.element}</small></span>`).join('')}</div><button class="primary" id="climb">${floor<=state.tower.highestCleared?'Replay':'Challenge'} floor ${floor} ↗</button></section></div>
 ${legendGallery()}${recruitmentBook()}${trainer.hasSession?autoSessionSummary():''}<section class="growth-guide"><div><span>01</span><h3>Every defeat counts</h3><p>Each defeated enemy awards account XP once. Higher-level enemies give more XP, and every companion grows together, including benched pets.</p></div><div><span>02</span><h3>Grow into your role</h3><p>Levels improve health, attack, defense, and recovery. New role abilities arrive at levels 3, 5, 8, and 12. Choose talents at account levels 25, 50, and 75.</p></div><div><span>03</span><h3>Build your next synergy</h3><p>New recruits join at your account level. Mix elemental attacks to trigger reactions and bring a new strategy to the next tower floor.</p></div></section>`;
}
function petDetails(){
 const p=accountPet(state,state.pets.find(p=>p.id===selected)||state.pets[0]),relic=equippedRelic(state,p.id),item=relic?.type,stats=petStats(p,relic),growth=progressionOf(p),moves=skillLibrary(p,relic),path=learnsets[p.role],kit=equippedMoves(p,relic);
 return `<div class="section-title"><button class="text-button" data-view="sanctuary">← Back to sanctuary</button><span class="pill">COMPANION DOSSIER</span></div><section class="dossier"><div class="dossier-portrait featured" style="--pet:${p.color}"><div class="feature-top">${roleBadge(p)}${elementBadge(p.element)}</div><div class="portrait-halo"></div>${petArt(p)}<span class="portrait-level">${p.legend?'✦ LEGEND · ':''}${growthStage(p).name.toUpperCase()} · ACCOUNT LEVEL <strong>${growth.level}</strong></span><h1>${esc(p.name)}</h1>${p.legend?`<span class="legend-title">${esc(p.title)} · Tower floor ${p.bossFloor}</span>`:''}<p class="species-label">${species[petSpecies(p)]} · ${state.teamIds.includes(p.id)?'On your battle team':'Resting in the sanctuary'}</p><p>${esc(p.lore)}</p><button class="primary" data-team="${esc(p.id)}">${state.teamIds.includes(p.id)?'Remove from team −':'Add to team ＋'}</button></div>
 <div class="dossier-stats"><p class="eyebrow">A LITTLE STRONGER EVERY DAY</p><h2>The spirit behind the spark.</h2><div class="level-summary"><strong>Account level ${growth.level}</strong><span>${growth.level<MAX_LEVEL?'Every companion grows at the next account level':'Fully grown. Still full of possibilities.'}</span>${xpBar(p)}</div><div class="stat-grid"><div><span>♥</span><strong>${stats.maxHp}</strong><small>Maximum health${relic?' · item included':''}</small></div><div><span>⚔</span><strong>${Math.round(stats.attack*100)}%</strong><small>Ability damage${relic?' · relic damage ×'+itemStats(relic).damage.toFixed(2):''}</small></div><div><span>⬡</span><strong>${Math.round(stats.defense*100)}%</strong><small>Damage reduction</small></div><div><span>❋</span><strong>${Math.round(stats.recovery*100)}%</strong><small>Healing & shield power</small></div></div><div class="dossier-traits"><p>${esc(roles[p.role].description)}</p><div>${elementBadge(p.element)}<span>Strong vs <b>${elements[p.element].beats}</b> · ${Object.keys(elements).find(id=>elements[id].beats===p.element)} resists your attacks.</span></div><p>Equipped: <b>${items[item]?.name||'No item'}</b>${relic?' · Lv.'+relic.level+' · '+esc(describeItem(relic)):''}</p></div></div></section>
 ${passiveCard(p)}${talentEditor(p)}${loadoutEditor(p,relic)}${growthGallery(p)}<section class="dossier-abilities"><div class="section-title"><div><p class="eyebrow">WHAT MAKES THEM EXTRAORDINARY</p><h2>Equipped for battle <span>${kit.length} / 4 skills</span></h2></div><span class="ability-note">Descriptions show base effects. Current power includes level and gear, before enemy defenses and element matchups.</span></div><div class="dossier-ability-grid">${kit.map(id=>abilityDossier(id,p,stats)).join('')}</div></section><details class="skill-library"><summary>Unlocked skill library · ${moves.length} skills</summary><div class="dossier-ability-grid">${moves.map(id=>abilityDossier(id,p,stats)).join('')}</div></details>
 <section class="ability-path"><div class="section-title"><div><p class="eyebrow">THE ROAD AHEAD</p><h2>A growing kind of magic.</h2></div><span class="ability-note">Unlocked by account level · choose what to equip</span></div><div class="unlock-grid">${path.map(([id,level])=>`<article class="unlock-card ${growth.level>=level?'learned':'locked'}"><span class="unlock-level">${growth.level>=level?'✓ LEARNED':'UNLOCK AT LEVEL '+level}</span><span class="ability-icon">${abilities[id].icon}</span><h3>${abilities[id].name}</h3><p>${abilities[id].description}</p><small>${growth.level>=level?'Unlocked · equip in one of your four slots':Math.max(0,level-growth.level)+' more level'+(level-growth.level===1?'':'s')}</small></article>`).join('')}</div></section>${elementAbilityPath(p,growth)}${inventory(p)}${elementGuide()}`;
}
function abilityDossier(id,p,stats){const a=abilities[id],factor=isRecovery(a)||isBarrier(a)?stats.recovery:stats.attack*itemStats(equippedRelic(state,p.id)).damage;return `<article class="dossier-ability"><span class="ability-icon">${a.icon}</span><div><h3>${a.name}${a.itemOnly?' <small>RELIC</small>':a.legendOnly?' <small>LEGEND ART</small>':''}</h3><p>${a.description}</p><div class="ability-facts"><span>${a.cooldown?'Cooldown-based skill':'Always-ready basic'}</span>${a.element?`<span>${elements[a.element].icon} ${a.element}${a.element==='Astral'?' lightning':''}</span>`:''}<span>${a.cooldown} round cooldown</span><span>${{self:'Self',ally:'One ally',enemy:'One enemy',allEnemies:'All enemies',allAllies:'All allies'}[a.target]}</span>${a.power?`<strong>Effect power ${Math.round(a.power*factor*(a.itemOnly?itemStats(equippedRelic(state,p.id)).abilityFactor:1))}</strong>`:''}</div></div></article>`;}
function bindProgression(){bindAutoTraining();document.querySelectorAll('[data-legend-floor]').forEach(el=>el.onclick=()=>{if(busy||trainer.running)return;chosenFloor=Number(el.dataset.legendFloor);view='adventure';render();document.querySelector('.tower-card')?.scrollIntoView({block:'start',behavior:'instant'});});
 document.querySelectorAll('[data-inspect]').forEach(el=>el.onclick=()=>{if(busy||trainer.running)return;selected=el.dataset.inspect;view='pet';notice='';render();window.scrollTo({top:0,behavior:'instant'});});
 document.querySelector('#training-tier')?.addEventListener('change',e=>{state.trainingTier=e.target.value;save();render();});
 document.querySelectorAll('[data-floor]').forEach(el=>el.onclick=()=>{chosenFloor=Number(el.dataset.floor);render();});
 document.querySelector('#train')?.addEventListener('click',()=>launchEncounter('training',1,state.trainingTier));
 document.querySelector('#climb')?.addEventListener('click',()=>launchEncounter('tower',chosenFloor));
 document.querySelector('#resume')?.addEventListener('click',()=>{view='battle';render();});
 document.querySelector('#speed')?.addEventListener('click',()=>{if(busy||trainer.running)return;state.quickAnimations=!state.quickAnimations;save();render();});
}

function battlePower(p,a){return Math.round(a.power*(a.itemOnly?p.itemBonuses.abilityFactor:1)*(isRecovery(a)||isBarrier(a)?p.healingFactor:p.attackFactor*attackMultiplier(p)));}

function trainingFocusOptions(){return `<option value="discover" ${state.trainingTarget==='discover'?'selected':''}>Discover missing companions</option><option value="rotation" ${state.trainingTarget==='rotation'?'selected':''}>Rotate the full roster</option>${trainingRoster(state).map(p=>`<option value="${p.id}" ${state.trainingTarget===p.id?'selected':''}>${esc(p.name)} · ${state.pets.some(q=>q.id===p.id)?'collected':p.element+' '+roles[p.role].name}</option>`).join('')}`;}
function recruitmentBook(){const roster=[...starters,...wilds],owned=roster.filter(p=>state.pets.some(q=>q.id===p.id)).length,target=trainingTargetPet(state);return `<section class="recruitment-book"><div class="section-title"><div><p class="eyebrow">MEET EVERY LITTLE SPIRIT</p><h2>Training companions <span>${owned} / ${roster.length}</span></h2><p class="intro">${owned===roster.length?'Collection complete! Keep training any pet for XP and relics.':'Every ordinary companion is recruitable here. Legends must first be won in their tower trials.'}</p></div><span class="pill">GUARANTEED ON VICTORY · NO DUPLICATES</span></div><div class="recruitment-grid">${roster.map(p=>{const mine=state.pets.find(q=>q.id===p.id);return `<article class="recruit-card ${mine?'owned':''} ${target.id===p.id?'focused':''}"><span class="recruit-state">${mine?'✓ COLLECTED':'UNDISCOVERED'}</span>${petArt(p)}<h3>${esc(p.name)}</h3><small>${roles[p.role].name} · ${p.element}${p.element==='Astral'?' lightning':''}</small><button data-recruit-focus="${p.id}" ${trainer.running?'disabled':''}>${target.id===p.id?'Current focus':mine?'Practice with this pet':'Focus recruitment'} ↗</button></article>`;}).join('')}</div></section>`;}
function autoSessionSummary(){const stats=trainer.stats;return `<div class="auto-session-summary"><strong>Auto-training session</strong><span>${stats.battles} battles · ${stats.wins} wins · ${stats.losses} defeats · ${stats.draws} draws · +${stats.xp} account XP · ${stats.recruits} new companions · ${stats.items} item drops</span><p>${esc(trainer.status)}</p><small>${esc(goalDescription(trainer.goals))}</small></div>`;}
function autoTrainingPanel(){return `<section class="auto-training-panel ${trainer.running?'auto-running':''}" aria-label="Auto-training controls"><div><span class="eyebrow">${trainer.active?'AUTO-TRAINING ACTIVE':trainer.running?'STOPPING AUTO-TRAINING':'TRAINING · YOUR PACE'}</span><h3>${trainer.active?'Battle. Grow. Meet someone new.':trainer.running?'Finishing the current turn…':'Let your team find its rhythm.'}</h3><p>${trainer.hasSession?esc(trainer.status):'Automatic battles use legal skills, collect rewards, and stop when a goal is reached.'}</p>${trainer.hasSession?`<div class="auto-counters"><span>${trainer.stats.battles} battles</span><span>${trainer.stats.wins} wins</span><span>${trainer.stats.losses} defeats</span><span>${trainer.stats.draws} draws</span><span>+${trainer.stats.xp} XP</span><span>${trainer.stats.recruits} new pets</span><span>${trainer.stats.items} item drops</span></div>`:''}</div><button class="primary ${trainer.running?'auto-stop':'auto-start'}" id="${trainer.running?'stop-auto':'auto-battle-start'}" ${trainer.running?!trainer.active?'disabled':'':busy?'disabled':''}>${trainer.running?trainer.active?'Stop auto-training ■':'Stopping…':'Start auto-training ⟳'}</button></section>${trainingGoalEditor()}`;}
function startAutoTraining(){
 if(busy||trainer.running)return;for(const input of document.querySelectorAll('.training-goals input'))if(!input.reportValidity())return;
 autoTier=state.trainingTier;state.quickAnimations=true;save();
 if(view!=='battle'||!battle||battle.context.mode!=='training'||battle.outcome){if(battle?.outcome==='won'&&!battle.claimed&&battle.context.mode==='training'){claimEncounter(state,battle);save();}launchEncounter('training',1,autoTier);}
 trainer.start();
}
function bindAutoTraining(){
 bindTrainingGoalControls();document.querySelector('#start-auto')?.addEventListener('click',startAutoTraining);document.querySelector('#auto-battle-start')?.addEventListener('click',startAutoTraining);document.querySelector('#stop-auto')?.addEventListener('click',()=>trainer.stop());
 document.querySelector('#training-target')?.addEventListener('change',e=>{if(trainer.running)return;state.trainingTarget=e.target.value;save();render();});
 document.querySelectorAll('[data-recruit-focus]').forEach(el=>el.onclick=()=>{if(trainer.running)return;state.trainingTarget=el.dataset.recruitFocus;save();render();document.querySelector('.training-card')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});
}

function elementAbilityPath(p,growth){const theme=p.element==='Astral'?'Astral lightning':p.element;return `<section class="ability-path element-path"><div class="section-title"><div><p class="eyebrow">MAGIC IN THEIR NATURE</p><h2>${elements[p.element].icon} ${theme} arts</h2></div><span class="ability-note">Element skills unlock at levels 1, 3, 6, and 10, alongside role skills.</span></div><div class="unlock-grid">${elementalLearnsets[p.element].map(([id,level])=>`<article class="unlock-card ${growth.level>=level?'learned':'locked'}"><span class="unlock-level">${growth.level>=level?'✓ LEARNED':'UNLOCK AT LEVEL '+level}</span><span class="ability-icon">${abilities[id].icon}</span><h3>${abilities[id].name}</h3><p>${abilities[id].description}</p><small>${growth.level>=level?'Unlocked · equip in one of your four slots':Math.max(0,level-growth.level)+' more level'+(level-growth.level===1?'':'s')}</small></article>`).join('')}</div></section>`;}

function growthGallery(p){const stage=growthStage(p);return `<section class="growth-gallery"><div class="section-title"><div><p class="eyebrow">A SPIRIT THAT GROWS WITH YOU</p><h2>Four stages. One companion.</h2></div><span class="ability-note">All companions grow automatically at account levels 5, 10, and 15. Maximum level: 100.</span></div><div class="stage-gallery-grid">${GROWTH_STAGES.map(s=>`<article class="stage-preview ${s.index===stage.index?'current':s.index<stage.index?'reached':'future'}" data-stage-card="${s.index}"><span>${s.index===stage.index?'CURRENT STAGE':s.index<stage.index?'✓ REACHED':'GROWTH PREVIEW'}</span>${petArt({...p,level:s.minLevel})}<h3>${s.name}</h3><small>Levels ${s.minLevel}–${s.maxLevel}</small><p>${s.description}</p></article>`).join('')}</div></section>`;}
function legendTrialPreview(p,level){const obtained=state.pets.some(q=>q.id===p.id);return `<div class="legend-trial-preview">${petArt({...p,level,boss:true})}<div><span class="legend-tag">✦ LEGEND TRIAL</span><h3>${p.name}</h3><p>${p.title} · ${growthStage(level).name} · Lv.${level}</p><small>${obtained?'Already collected · train and grow your Legend.':'Guaranteed recruitment at your account level after victory.'}</small></div></div>`;}
function legendGallery(){return `<section class="legend-gallery"><div class="section-title"><div><p class="eyebrow">THE FOUR KEEPERS OF THE SPIRE</p><h2>Legends worth growing with.</h2><p class="intro">One recruitable Legend every five floors. Previously cleared trials can be replayed for their new Legend reward.</p></div><span class="pill">GUARANTEED RECRUITMENT · ACCOUNT LEVEL</span></div><div class="legend-gallery-grid">${legends.map(p=>{const owned=state.pets.find(q=>q.id===p.id),mine=owned?accountPet(state,owned):null,open=p.bossFloor<=state.tower.highestCleared+1;return `<article class="legend-collection-card ${mine?'owned':''}"><div><span class="legend-tag">✦ ${p.element.toUpperCase()} LEGEND</span><small>FLOOR ${p.bossFloor}</small></div>${petArt({...p,level:mine?.level||towerFloorInfo(p.bossFloor).level})}<h3>${p.name}</h3><p>${p.title}</p><span>${roles[p.role].name} · ${species[p.species]} · ${mine?growthStage(mine).name:'Trial Lv.'+towerFloorInfo(p.bossFloor).level}</span><small>${mine?'✓ Recruited · Level '+mine.level:open?'Trial available · defeat to recruit':'Reach floor '+p.bossFloor+' to challenge'}</small><button ${mine?`data-inspect="${p.id}"`:`data-legend-floor="${p.bossFloor}"`} ${!mine&&!open?'disabled':''}>${mine?'View Legend & growth ↗':'View trial ↗'}</button></article>`;}).join('')}</div></section>`;}

function passiveCard(p){const passive=passiveOf(p);return `<section class="passive-card"><span>${passive.icon}</span><div><small>${passive.legend?'INNATE LEGEND PASSIVE':'INNATE ANIMAL PASSIVE'} · NO SKILL SLOT</small><h3>${passive.name}</h3><p>${esc(passive.description)}</p></div></section>`;}
function loadoutEditor(p,relic){const kit=equippedMoves(p,relic),library=skillLibrary(p,relic);return `<section class="skill-loadout"><div class="section-title"><div><p class="eyebrow">MAKE EVERY TURN YOUR OWN</p><h2>Four skills. Your strategy.</h2><p class="intro">One always-ready basic and up to three chosen skills. Changes save immediately and apply to the next encounter.</p></div><span class="pill">NO ENERGY · COOLDOWNS ONLY</span></div><div class="loadout-slots">${Array.from({length:4},(_,i)=>{const id=kit[i],a=abilities[id];return `<article class="loadout-slot"><label>${i===0?'01 · BASIC ATTACK':String(i+1).padStart(2,'0')+' · EQUIPPED SKILL'}<select data-skill-slot="${i}" aria-label="Skill slot ${i+1}" ${i===0?'disabled':''}>${i?'<option value="">Empty slot</option>':''}${library.filter(move=>i===0?move===basicMove(p):move!==basicMove(p)).map(move=>`<option value="${move}" ${id===move?'selected':''}>${esc(abilities[move].name)} · ${abilities[move].cooldown?abilities[move].cooldown+' turns':'Basic'}</option>`).join('')}</select></label><span class="ability-icon">${a?.icon||'＋'}</span><p>${a?.description||'Choose any unlocked skill, including a skill granted by your equipped relic.'}</p></article>`;}).join('')}</div></section>`;}
function bindBuildControls(){
 document.querySelectorAll('[data-copy]').forEach(el=>el.onchange=()=>{bagSelection[el.dataset.copy]=el.value;render();});
 document.querySelectorAll('[data-skill-slot]').forEach(el=>el.onchange=()=>{if(busy||trainer.running)return;const p=state.pets.find(p=>p.id===selected),relic=equippedRelic(state,p.id),prepared=accountPet(state,p),kit=equippedMoves(prepared,relic),slot=Number(el.dataset.skillSlot),duplicate=kit.indexOf(el.value),old=kit[slot];if(duplicate>0&&duplicate!==slot)kit[duplicate]=old;kit[slot]=el.value;const next=kit.filter(Boolean);if(setSkillLoadout(prepared,next,relic)){p.equippedSkills=[...prepared.equippedSkills];resetBattle();save();notice='Loadout saved. '+p.name+' will bring '+next.length+' skills into the next encounter.';}render();});
}
function bossBattlePanel(b){if(!b.context.boss)return '';const boss=b.enemies.find(p=>p.boss),profile=bossProfile(boss);if(!profile)return '';return `<section class="boss-mechanic-panel"><div><p class="eyebrow">LEGEND BOSS · ${esc(profile.lair).toUpperCase()}</p><h2>${esc(boss.name)} <span>PHASE ${boss.bossPhase===2?'II · AWAKENED':'I'}</span></h2><p>${esc(profile.rule)}</p></div><div class="boss-telegraph"><strong>${b.outcome?'Trial complete':b.round>=boss.nextSpecialRound?'⚠ CHARGED · NEXT BOSS ACTION':'⚠ CHARGING · ROUND '+boss.nextSpecialRound}</strong><span>${abilities[profile.special].icon} ${abilities[profile.special].name} · all enemies</span><small>Summon waves: ${boss.summonWaves}/2 · Minions act from the following round.<br>At 50% HP: Phase II, +15% attack, shield, and a reinforcement wave. Defeat the Legend to disperse its summons.</small></div></section>`;}
function trainingLootSummary(b){if(b.context.mode!=='training')return '';const loot=b.trainingLoot;return `<div class="loot-summary"><strong>${loot?.items.length?'✦ TRAINING DROP SECURED':'TRAINING LOOT ROLL'}</strong><p>${loot?.items.length?loot.items.map(i=>items[i.id].icon+' '+items[i.id].name+' · Level 1 · saved to satchel').join(', '):'No relic this encounter. '+Math.round((TRAINING_DROP_CHANCE[b.context.tier]||.35)*100)+'% chance each completed encounter.'}</p></div>`;}

function saveScreen(){const desktop=!!desktopBridge;let backup=false;try{backup=!!localStorage.getItem('lumenwild-before-import');}catch{}return `<div class="page-heading"><div><p class="eyebrow">YOUR COMPANIONS. YOUR PROGRESS.</p><h1>A journey <em>worth keeping.</em></h1><p class="intro">Lumenwild ${GAME_VERSION} · ${desktop?'Desktop save on this PC':'Browser save on this device'}<br>Account level, companions, skill builds, items, and tower progress travel together.</p></div></div><section class="save-panel"><h2>${desktop?'Saved beyond the game folder.':'Take your progress with you.'}</h2><p>${desktop?'Updates replace the game files while your save stays in your Windows profile. A previous-save backup is kept automatically.':'Your browser saves automatically. Export a backup before moving the game, changing browsers, or switching to the desktop launcher.'}</p>${desktop?`<div class="save-location"><span>Save location</span><code>${esc(desktopBridge.saveDirectory)}${desktopBridge.saveDirectory?.includes('\\')?'\\':'/'}save.json</code></div>`:''}<div class="save-actions"><button class="primary" id="export-save">Export save backup ↓</button><button class="secondary" id="import-save">Import save backup ↑</button>${backup?'<button class="text-button" id="undo-import">Restore progress from before the last import</button>':''}<input type="file" id="save-file" accept=".json,application/json" hidden></div><p class="save-help">Import replaces your current collection. Your previous progress is kept so you can undo an import. Saves from older game versions migrate automatically.</p></section>${nativeUpdatePanel()}`;}
function bindSaveControls(){
 document.querySelector('#export-save')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify(saveEnvelope(state),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Lumenwild-save-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 document.querySelector('#import-save')?.addEventListener('click',()=>document.querySelector('#save-file').click());
 document.querySelector('#save-file')?.addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file||busy||trainer.running)return;try{if(file.size>4*1024*1024)throw new Error('This save is too large to import.');const raw=readSaveData(await file.text()),next=restoreSave(raw);if(next.pets.length!==new Set(raw.pets.map(p=>p.id)).size)throw new Error('Some pets could not be read. Your current progress was kept.');try{localStorage.setItem('lumenwild-before-import',JSON.stringify(saveEnvelope(state)));}catch{}state=next;saveBlocked=false;resetBattle();selected=state.teamIds[0];chosenFloor=Math.min(TOWER_FLOORS,state.tower.highestCleared+1);notice='Save imported. Your companions are ready to continue.';save();render();}catch(error){notice=error.message;render();}});
 document.querySelector('#undo-import')?.addEventListener('click',()=>{try{const previous=readSaveData(localStorage.getItem('lumenwild-before-import'));state=restoreSave(previous);saveBlocked=false;resetBattle();selected=state.teamIds[0];chosenFloor=Math.min(TOWER_FLOORS,state.tower.highestCleared+1);save();notice='Your progress from before the last import was restored.';render();}catch(error){notice=error.message;render();}});
}

function nativeUpdatePanel(){
 if(!nativeApp)return `<section class="save-panel update-info"><p class="eyebrow">KEEP YOUR SAVE. GROW YOUR GAME.</p><h2>Updates and existing progress.</h2><p>The installed Windows game checks for updates, downloads them in the background, and installs when you exit. Export your browser save and import it into the installed game to continue your journey.</p><p>${desktopBridge?'For the older command-file launcher, close the game and replace the entire extracted folder with the newer release.':'For the browser version, keep the same file location or import an exported backup into the new version.'}</p></section>`;
 const update=nativeUpdateState,checking=update.phase==='checking',downloading=update.phase==='downloading',ready=update.phase==='ready';
 return `<section class="save-panel update-info" id="native-updates"><p class="eyebrow">NEW ADVENTURES. THE SAME COMPANIONS.</p><h2>Game updates.</h2><div class="update-version"><span>Installed · ${esc(update.currentVersion||GAME_VERSION)}</span>${update.availableVersion?`<strong>${ready?'Ready':'New version'} · ${esc(update.availableVersion)}</strong>`:''}</div><p class="update-message" role="status">${esc(update.message)}</p>${downloading?`<div class="update-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(update.percent)}"><i style="width:${update.percent}%"></i></div><small>${Math.round(update.percent)}% downloaded</small>`:''}<div class="save-actions"><button class="${ready?'primary':'secondary'}" id="${ready?'install-update':'check-update'}" ${checking||downloading||update.phase==='unsupported'?'disabled':''}>${ready?'Restart & update ↗':checking?'Checking…':downloading?'Downloading…':'Check for updates ↻'}</button></div><p class="save-help">Updates download while you play and install after the game saves and exits. Restart now to apply a ready update immediately. Your progress and a pre-update backup stay on this PC.</p></section>`;
}
function bindNativeUpdateControls(){
 document.querySelector('#check-update')?.addEventListener('click',()=>nativeApp?.checkForUpdates().catch(()=>setNativeUpdateState({...nativeUpdateState,phase:'error',message:'Could not check for updates. You can keep playing offline.'})));
 document.querySelector('#install-update')?.addEventListener('click',()=>nativeApp?.installUpdate().catch(error=>{notice=error.message;render();}));
}
function setNativeUpdateState(status){nativeUpdateState=status;const panel=document.querySelector('#native-updates');if(panel){panel.outerHTML=nativeUpdatePanel();bindNativeUpdateControls();}const indicator=document.querySelector('#update-indicator');if(indicator)indicator.hidden=status.phase!=='ready';}
if(nativeApp){nativeApp.getUpdateStatus().then(setNativeUpdateState).catch(()=>{});nativeApp.onUpdateStatus(setNativeUpdateState);}
window.LUMENWILD_FLUSH_SAVE=async()=>{trainer.stop();const started=Date.now();while(busy){if(Date.now()-started>12000)throw new Error('The current turn is still resolving. Try exiting after it finishes.');await delay(40);}if(!saveBlocked){save();await desktopWriter?.flush();}return {saved:!saveBlocked};};

function accountBanner(){const growth=accountProgress(state);return `<section class="account-banner" aria-label="Account progression"><div class="account-level"><span>✧</span><div><small>ACCOUNT LEVEL</small><strong>${growth.level}<span> / ${MAX_LEVEL}</span></strong></div></div><div class="account-track">${xpBar()}</div><p>One level. Every companion.<br>Stats, skills & growth scale.</p></section>`;}
function collectionControls(count){const prefs=state.collection;return `<div class="collection-controls"><label>Sort pets<select id="pet-sort">${[['collected','Collection order'],['name','Name'],['element','Element'],['role','Role']].map(([id,label])=>`<option value="${id}" ${prefs.sort===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Element<select id="pet-element"><option value="all">All elements</option>${Object.keys(elements).map(id=>`<option value="${id}" ${prefs.element===id?'selected':''}>${id}</option>`).join('')}</select></label><label>Role<select id="pet-role"><option value="all">All roles</option>${Object.entries(roles).map(([id,r])=>`<option value="${id}" ${prefs.role===id?'selected':''}>${r.name}</option>`).join('')}</select></label><span class="collection-count" role="status">${count} / ${state.pets.length} pets</span>${prefs.element!=='all'||prefs.role!=='all'?'<button class="text-button" id="clear-pet-filters">Clear filters ×</button>':''}</div>${count?'':'<p class="empty-collection" role="status">No companions match these filters. Try another element or role.</p>'}`;}
function bindCollectionControls(){for(const [id,key]of [['pet-sort','sort'],['pet-element','element'],['pet-role','role']])document.getElementById(id)?.addEventListener('change',event=>{state.collection[key]=event.target.value;save();render();document.getElementById(id)?.focus();});document.querySelector('#clear-pet-filters')?.addEventListener('click',()=>{state.collection.element='all';state.collection.role='all';save();render();document.querySelector('#pet-element')?.focus();});}
function reactionGuide(){return `<details class="reaction-guide"><summary>Element combinations <span>Two elements. One reaction.</span></summary><p>Damaging skills, including basic attacks, leave an elemental aura for 2 round ends, including this round. Hit that target with a different element before the aura expires to trigger a reaction. Either order works; both teams can use them. The aura is consumed, so reactions cannot chain themselves. Healing, shields, passives, counters, and burn ticks do not apply auras. Cleansing removes them.</p><div class="reaction-grid">${ELEMENT_REACTIONS.map(r=>`<article class="reaction-card reaction-${r.id}"><div>${r.elements.map(elementBadge).join('<b>+</b>')}</div><h3>${r.icon} ${r.name}</h3><p>${r.description}</p></article>`).join('')}</div><p>Listed power scales with the triggering pet’s account or enemy level and equipment. Bonus damage respects shields, armor, and buffs, ignores type multipliers, and cannot trigger retaliation. Conduction and Bloom trigger once per skill, even when several auras react.</p></details>`;}
function reactionHint(actor,a){if(!a.power||!['enemy','allEnemies'].includes(a.target))return '';const legal=legalTargets(battle,'player',moveId,actor.cid),targets=a.target==='allEnemies'?legal:legal.filter(p=>p.cid===targetId),names=[...new Set(targets.map(p=>reactionFor(p.elementalAura?.element,abilityElement(actor,a))?.name).filter(Boolean))];return names.length?`<small class="reaction-ready">✧ Reaction ready: ${names.join(' · ')}</small>`:'';}

function talentEditor(p){const chosen=activeTalents(p);return `<section class="talent-editor"><div class="section-title"><div><p class="eyebrow">MAKE THEIR STRENGTH YOUR OWN</p><h2>A path of their own. <span>${chosen.length} / 3 talents</span></h2><p class="intro">Choose one talent at each milestone. Choices are unique to this pet, cost nothing to change, and apply next encounter. Talents use no skill slots.</p></div></div><div class="talent-tiers">${TALENT_LEVELS.map(level=>{const unlocked=p.level>=level,selected=p.talents?.[level],choices=talentChoices(p,level);return `<article class="talent-tier ${unlocked?'unlocked':'locked'}" data-talent-tier="${level}"><div class="talent-tier-heading"><strong>LEVEL ${level} · ${level===25?'ROLE PATH':level===50?p.element.toUpperCase()+' PATH':'ROLE MASTERY'}</strong><span>${unlocked?selected?'✓ CHOSEN':'CHOOSE ONE':'Unlocks at account level '+level}</span>${unlocked&&selected?`<button class="text-button" data-reset-talent="${level}">Reset choice ×</button>`:''}</div><div class="talent-options">${choices.map(t=>`<button class="talent-choice ${selected===t.id?'chosen':''}" data-talent="${t.id}" data-talent-level="${level}" aria-pressed="${selected===t.id}" ${unlocked?'':'disabled'}><span>${selected===t.id?'✦ SELECTED':unlocked?'✧ CHOOSE TALENT':'◇ LOCKED'}</span><h3>${t.name}</h3><p>${esc(t.description)}</p></button>`).join('')}</div></article>`;}).join('')}</div></section>`;}
function bindTalentControls(){
 const apply=(level,id)=>{if(busy||trainer.running)return;if(chooseTalent(state,selected,level,id)){resetBattle();save();notice='Talent choice saved. It takes effect next encounter.';render();document.querySelector('[data-talent-tier="'+level+'"]')?.scrollIntoView({block:'center',behavior:'instant'});}};
 document.querySelectorAll('[data-talent]').forEach(el=>el.onclick=()=>apply(Number(el.dataset.talentLevel),el.dataset.talent));document.querySelectorAll('[data-reset-talent]').forEach(el=>el.onclick=()=>apply(Number(el.dataset.resetTalent),null));
}
function trainingGoalEditor(){const goals=state.trainingGoals;return `<fieldset class="training-goals" ${trainer.running||busy?'disabled':''}><legend>Auto-training goals</legend><div class="training-goal-fields"><label>Stop after battles<input id="goal-battles" type="number" min="0" max="999" step="1" value="${goals.battleLimit}"><small>0 = unlimited · this session</small></label><label>Stop at account level<input id="goal-level" type="number" min="0" max="100" step="1" value="${goals.targetLevel}"><small>0 = no level goal</small></label><label>Stop when an item drops<select id="goal-item"><option value="none">No item goal</option><option value="any" ${goals.item==='any'?'selected':''}>Any new item drop</option>${Object.entries(items).map(([id,item])=>`<option value="${id}" ${goals.item===id?'selected':''}>${item.name}</option>`).join('')}</select><small>New drops only · owned items do not count</small></label></div><p data-goal-description>${esc(goalDescription(goals))}</p><p class="goal-help">The first goal reached finishes the encounter, collects rewards, and stops before the next battle. Manual Stop finishes only the current turn. Keep the game open.</p></fieldset>`;}
function bindTrainingGoalControls(){
 const update=(key,value)=>{if(trainer.running||busy)return;state.trainingGoals=trainingGoals({...state.trainingGoals,[key]:value});save();document.querySelectorAll('[data-goal-description]').forEach(el=>el.textContent=goalDescription(state.trainingGoals));};
 for(const [id,key]of [['goal-battles','battleLimit'],['goal-level','targetLevel']]){const input=document.getElementById(id);if(!input)continue;input.oninput=()=>{if(input.validity.valid&&input.value!=='')update(key,input.valueAsNumber);};input.onchange=()=>{if(input.value===''){input.value='0';update(key,0);}};}
 document.querySelector('#goal-item')?.addEventListener('change',event=>update('item',event.target.value));
}
